import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.Cq0X4QeM.js";const p=JSON.parse('{"title":"SCCM Hierarchy takeover","description":"","frontmatter":{"authors":"BlWasp, ShutdownRepo, felixbillieres","category":"ad"},"headers":[],"relativePath":"ad/movement/sccm-mecm/lateral-movement/hierarchy-takeover.md","filePath":"ad/movement/sccm-mecm/lateral-movement/hierarchy-takeover.md"}'),o={name:"ad/movement/sccm-mecm/lateral-movement/hierarchy-takeover.md"};function n(s,e,c,h,l,m){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="sccm-hierarchy-takeover" tabindex="-1">SCCM Hierarchy takeover <a class="header-anchor" href="#sccm-hierarchy-takeover" aria-label="Permalink to &quot;SCCM Hierarchy takeover&quot;">​</a></h1><h2 id="theory" tabindex="-1">Theory <a class="header-anchor" href="#theory" aria-label="Permalink to &quot;Theory&quot;">​</a></h2><p>As indicated by <a href="https://mobile.twitter.com/_mayyhem" target="_blank" rel="noreferrer">Chris Thompson</a> in his article <a href="https://posts.specterops.io/sccm-hierarchy-takeover-41929c61e087" target="_blank" rel="noreferrer">SCCM Hierarchy Takeover</a>, by default, when a new user is promoted to any SCCM administrative role on a primary site server (for example, <code>Full Administrator</code>), the role is automatically propagated to the other SCCM site in the hierarchy by the CAS.</p><p>This means that there is no security boundary between SCCM sites in the same hierarchy, and taking over one SCCM site implies the ability to take over all the others.</p><div class="tip custom-block"><p>For additional attack techniques and defense strategies related to SCCM hierarchy takeover, refer to the following techniques from the <a href="https://github.com/subat0mik/Misconfiguration-Manager/tree/main/attack-techniques" target="_blank" rel="noreferrer">Misconfiguration-Manager repository</a>:</p><ul><li><a href="https://github.com/subat0mik/Misconfiguration-Manager/blob/main/attack-techniques/TAKEOVER/TAKEOVER-4/takeover-4_description.md" target="_blank" rel="noreferrer">TAKEOVER-4: Relay CAS to Child</a></li><li><a href="https://github.com/subat0mik/Misconfiguration-Manager/blob/main/attack-techniques/TAKEOVER/TAKEOVER-5/takeover-5_description.md" target="_blank" rel="noreferrer">TAKEOVER-5: Hierarchy Takeover via NTLM coercion and relay to AdminService on remote SMS Provider</a></li></ul></div><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><h3 id="automatic-propagation" tabindex="-1">Automatic propagation <a class="header-anchor" href="#automatic-propagation" aria-label="Permalink to &quot;Automatic propagation&quot;">​</a></h3><p>There is nothing to do. Just promote a user to any SCCM administrative role on a primary site server (for example, <code>Full Administrator</code>), and the role will be automatically propagated to the other SCCM site in the hierarchy by the CAS.</p><h3 id="takeover-5-ntlm-coercion-and-relay-to-adminservice" tabindex="-1">TAKEOVER-5: NTLM coercion and relay to AdminService <a class="header-anchor" href="#takeover-5-ntlm-coercion-and-relay-to-adminservice" aria-label="Permalink to &quot;TAKEOVER-5: NTLM coercion and relay to AdminService&quot;">​</a></h3><div class="caution custom-block"><p>This technique only works on Configuration Manager versions prior to 2509. Version 2509 and later reject NTLM authentication at the AdminService. For more details, see <a href="https://learn.microsoft.com/en-us/intune/configmgr/core/plan-design/changes/whats-new-in-version-2509#adminservice-now-rejects-ntlm-authentication" target="_blank" rel="noreferrer">Microsoft&#39;s update notes</a>.</p></div><p>This technique allows an attacker to take over the SCCM hierarchy by relaying coerced NTLM authentication from site servers to remote SMS Providers via the AdminService API. The SMS Provider&#39;s AdminService REST API uses Microsoft Negotiate for authentication and, in default configurations prior to version 2509, was vulnerable to NTLM relay attacks.</p><div class="tip custom-block"><p>For detailed requirements, defensive strategies, and practical implementation steps, refer to the <a href="./../privilege-escalation/site-takeover#relay-to-the-http-api-adminservice">Relay to the HTTP API AdminService</a> section in the site takeover article, <a href="https://github.com/subat0mik/Misconfiguration-Manager/blob/main/attack-techniques/TAKEOVER/TAKEOVER-5/takeover-5_description.md" target="_blank" rel="noreferrer">TAKEOVER-5</a>, and the article &quot;<a href="https://posts.specterops.io/site-takeover-via-sccms-adminservice-api-d932e22b2bf" target="_blank" rel="noreferrer">Site Takeover via SCCM&#39;s AdminService API</a>&quot; by <a href="https://twitter.com/garrfoster" target="_blank" rel="noreferrer">Garrett Foster</a>.</p></div><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p><a href="https://posts.specterops.io/sccm-hierarchy-takeover-41929c61e087" target="_blank" rel="noreferrer">https://posts.specterops.io/sccm-hierarchy-takeover-41929c61e087</a></p><p><a href="https://github.com/subat0mik/Misconfiguration-Manager/blob/main/attack-techniques/TAKEOVER/TAKEOVER-4/takeover-4_description.md" target="_blank" rel="noreferrer">https://github.com/subat0mik/Misconfiguration-Manager/blob/main/attack-techniques/TAKEOVER/TAKEOVER-4/takeover-4_description.md</a></p><p><a href="https://github.com/subat0mik/Misconfiguration-Manager/blob/main/attack-techniques/TAKEOVER/TAKEOVER-5/takeover-5_description.md" target="_blank" rel="noreferrer">https://github.com/subat0mik/Misconfiguration-Manager/blob/main/attack-techniques/TAKEOVER/TAKEOVER-5/takeover-5_description.md</a></p><p><a href="https://x.com/_Mayyhem/status/2014005215398101036" target="_blank" rel="noreferrer">https://x.com/_Mayyhem/status/2014005215398101036</a></p>',17)]))}const u=t(o,[["render",n]]);export{p as __pageData,u as default};
